// Enhance the SVGs generated by Platane/snk and create motion-free alternatives.
// Run after the upstream action, or after generate-snake-animation@3.5.0 locally.
import { readFile, writeFile } from 'node:fs/promises';

const reducedMotionRule = '@media(prefers-reduced-motion:reduce){*{animation:none!important}.s,.u{display:none}}';

function removeKeyframes(styles) {
  const pattern = /@keyframes\s+[^{}]+\{/g;
  let result = '';
  let cursor = 0;
  let match;
  while ((match = pattern.exec(styles))) {
    result += styles.slice(cursor, match.index);
    let depth = 1;
    let end = pattern.lastIndex;
    while (depth > 0 && end < styles.length) {
      if (styles[end] === '{') depth += 1;
      if (styles[end] === '}') depth -= 1;
      end += 1;
    }
    if (depth !== 0) throw new Error('Unbalanced contribution animation CSS.');
    cursor = end;
    pattern.lastIndex = end;
  }
  return result + styles.slice(cursor);
}

function describe(svg, isStatic = false) {
  const description = isStatic
    ? "Static daily contribution activity from sriv144's real GitHub calendar. Generated with https://github.com/Platane/snk."
    : "A snake traverses sriv144's real GitHub contribution calendar. Reduced-motion preferences disable animation. Generated with https://github.com/Platane/snk.";
  return svg
    .replace(/<title\b[^>]*>[\s\S]*?<\/title>/g, '')
    .replace(/<desc\b[^>]*>[\s\S]*?<\/desc>/g, '')
    .replace(/<svg\b([^>]*)>/, (_, attributes) => {
      const clean = attributes.replace(/\s(?:role|aria-labelledby)="[^"]*"/g, '');
      return `<svg${clean} role="img" aria-labelledby="contribution-title contribution-desc"><title id="contribution-title">Srivatsan's GitHub contribution activity</title><desc id="contribution-desc">${description}</desc>`;
    });
}

for (const theme of ['light', 'dark']) {
  const path = new URL(`../assets/contributions-${theme}.svg`, import.meta.url);
  let svg = await readFile(path, 'utf8');
  if (!svg.includes('<svg') || !svg.includes('</style>') || !svg.includes('class="c')) {
    throw new Error(`Unexpected upstream SVG structure: ${path.pathname}`);
  }
  svg = svg.replace(/--cs:[^;}]+/g, `--cs:${theme === 'dark' ? '#5eead4' : '#087f75'}`);
  if (!svg.includes(reducedMotionRule)) {
    svg = svg.replace('</style>', `${reducedMotionRule}</style>`);
  }
  svg = describe(svg);
  await writeFile(path, svg);

  const still = describe(svg.replace(/<style>([\s\S]*?)<\/style>/, (_, styles) => {
    const staticStyles = removeKeyframes(styles).replace(/animation(?:-[a-z-]+)?:[^;}]+;?/g, '');
    return `<style>${staticStyles}.s,.u{display:none}</style>`;
  }), true);
  await writeFile(new URL(`../assets/contributions-${theme}-static.svg`, import.meta.url), still);
}
